def effective_limit(value, default=10):
    if value is None:
        return default
    elif value == 0:
        return 0
    elif value > 0:
        return value
    else:
        raise ValueError("effective_limit must be a non-negative integer or None")

import settings
import pytest

def test_effective_limit_none():
    assert settings.effective_limit(None) == 10

def test_effective_limit_zero():
    assert settings.effective_limit(0) == 0

def test_effective_limit_positive():
    assert settings.effective_limit(5) == 5

def test_effective_limit_negative_raises():
    with pytest.raises(ValueError):
        settings.effective_limit(-1)

def test_effective_limit_custom_default():
    assert settings.effective_limit(None, default=20) == 20
    assert settings.effective_limit(0, default=20) == 0
    assert settings.effective_limit(15, default=20) == 15

